const e={protocols:{name:"SACAA Summarised Medical Protocols in line with Part 67 (effective 16 November 2021), item 52",url:"https://caasanwebsitestorage.blob.core.windows.net/avmed-amended-protocols/Summarised%20Medical%20Protocols%20in%20line%20with%20Part%2067%20of%20the%20Civil%20Aviation%20Regulations%20and%20Technical%20Standards.pdf"},classes:{name:"SACAA: amended Part 67 regulation 67.00.2, classes of medical certificates",url:"https://caasanwebsitestorage.blob.core.windows.net/aviation-medicine-general-information/Ammended%20%20Part%2067%20Regulations%20Classes%20of%20medical%20certificates.pdf"},application:{name:"Civil Aviation Regulations, 2011, Part 67, regulation 67.00.7 (Application for medical certificates)",url:"https://api.acts.co.za/civil-aviation-act-2009/nr425_67_00_7_application.php"},class4:{name:"Civil Aviation Regulations, 2011, Part 67, regulation 67.00.5 (Class 4 medical certificates)",url:"https://api.acts.co.za/civil-aviation-act-2009/nr425_67_00_5_class_4_med.php"},cabin:{name:"Civil Aviation Regulations, 2011, Part 64, regulation 64.01.6 (Cabin crew medical fitness)",url:"https://source.acts.co.za/civil-aviation-act-2009/nr425_64_01_6_medical_fit.php"},am007:{name:"SACAA procedure AM007: issuing of Class I, II, III and IV medical certificates (reissued 15 September 2025)",url:"https://caasanwebsitestorage.blob.core.windows.net/shared-documents/AM007%20Issuing%20of%20a%20class%20IIIIII%20and%20IV%20medical%20certificate.pdf"},avmed:{name:"SACAA Aviation Medicine page",url:"https://www.caa.co.za/industry-information/aviation-medicine/"},faq:{name:"SACAA Frequently Asked Questions (medical classes and validity periods, Class 4 for cabin crew, who may examine, extensions)",url:"https://www.caa.co.za/information-for-the-public/frequently-asked-questions/"},register:{name:"SACAA list of Regular Designated Aviation Medical Examiners (Dr AO Ndhlovu, MR 336)",url:"https://caasanwebsitestorage.blob.core.windows.net/shared-documents/Regular%20DAMES.pdf"},form:{name:"SACAA form CA 67-02(a), Aviation Medical Report",url:"https://caasanwebsitestorage.blob.core.windows.net/aviation-medicine-forms-and-checklist/CA%2067-02%28a%29.pdf"},classesReg:{name:"Civil Aviation Regulations, 2011, Part 67, regulation 67.00.2 (Classes of medical certificates)",url:"https://api.acts.co.za/civil-aviation-act-2009/nr425_67_00_2_classes_of_.php"},designation:{name:"Civil Aviation Regulations, 2011, Part 67, regulation 67.00.4 (Designation of aviation medical examiners)",url:"https://api.acts.co.za/civil-aviation-act-2009/nr425_67_00_4_designation.php"},validityReg:{name:"Civil Aviation Regulations, 2011, Part 67, regulation 67.00.6 (Period of validity and extensions)",url:"https://api.acts.co.za/civil-aviation-act-2009/nr425_67_00_6_period_of_v.php"},issuing:{name:"Civil Aviation Regulations, 2011, Part 67, regulation 67.00.8 (Issuing of medical certificate)",url:"https://api.acts.co.za/civil-aviation-act-2009/nr425_67_00_8_issuing_of_.php"},duties:{name:"Civil Aviation Regulations, 2011, Part 67, regulation 67.00.9 (Duties of holder of medical certificate)",url:"https://api.acts.co.za/civil-aviation-act-2009/nr425_67_00_9_duties_of_h.php"},records:{name:"Civil Aviation Regulations, 2011, Part 67, regulation 67.00.12 (Period of validity of medical records)",url:"https://api.acts.co.za/civil-aviation-act-2009/nr425_67_00_12_period_of_.php"},suspension:{name:"Civil Aviation Regulations, 2011, Part 67, regulation 67.00.14 (Suspension or cancellation of medical certificate)",url:"https://api.acts.co.za/civil-aviation-act-2009/nr425_67_00_14_suspension.php"},spl:{name:"Civil Aviation Regulations, 2011, Part 61, regulation 61.02.1 (Requirements for SPL or ISPL, as amended 21 August 2026)",url:"https://api.acts.co.za/civil-aviation-act-2009/nr425_61_02_1_requirements.php"}},i={slug:"renew-sacaa-class-2-medical",title:"Class 2 Medical Renewal, Step by Step | ClinoTrend",h1:"How to renew your SACAA Class 2 medical, step by step",description:"Renew a SACAA Class 2 medical in South Africa: when to book, which examiner, what to bring, what happens on the day, and how to apply for a 30 day extension.",excerpt:"When to book, which examiner can renew it, what to bring, what happens on the day, and what to do if your certificate is about to expire.",keyword:"class 2 medical renewal",question:"How do I renew my SACAA Class 2 medical?",answer:"Check the expiry date on your certificate, then book a SACAA Designated Aviation Medical Examiner a few weeks before it. Bring your ID, licence, current certificate, logbook and a list of your medicines. If you meet the standards, the certificate can be issued on the day. Apply to SACAA for an extension at least 15 days before expiry if needed.",facts:["Under Part 67, a Class 2 certificate is valid for 60 months if you are less than 40, 24 months after your 40th birthday, and 12 months after your 50th birthday.","Aviation medicals start from R1,500. Extra tests or reports are added only if the doctor finds they are needed during the medical. We confirm the fee when you book.","Dr A.O. Ndhlovu, SACAA Regular DAME MR 336, does Class 2 renewals at Grand Central Airport, Midrand."],secondary:["sacaa class 2 medical certificate","class 2 medical certificate south africa","sacaa medical extension","sacaa medical examiners"],published:"2026-11-10",updated:"2026-11-10",status:"approved",tag:"Renewals",body:[{t:"p",x:"If you fly on a student pilot licence (SPL) or a private pilot licence (PPL), your licence is only valid while you hold a current Class 2 medical certificate. Renewing it is routine, but a little planning avoids a gap in flying. This guide walks through the renewal in the order you will meet each step, with the South African Civil Aviation Regulations (Part 67) quoted where it matters."},{t:"h2",x:"Who needs a Class 2 medical?",id:"who"},{t:"p",x:"Under the amended regulation 67.00.2 of Part 67, a Class 2 medical certificate covers, among others, the SPL, the PPL for aeroplane, airship and helicopter, the flight engineer licence, the free balloon commercial pilot licence and the commercial glider pilot. The same regulation says that a pilot holding a valid Class 1 certificate is deemed to hold a valid Class 2 and Class 4 certificate."},{t:"p",x:"Cabin crew may need a Class 2 or a Class 4 medical, depending on what the airline or operator asks for. If you are cabin crew, read our guide to [cabin crew medical requirements](/blog/cabin-crew-medical-class-4-south-africa/)."},{t:"h2",x:"How do I check my expiry date?",id:"expiry"},{t:"p",x:"Look at the expiry date printed on your current certificate. Certificates run to the **last day of a month**. Under Part 67, regulation 67.00.6(3), a Class 2 certificate is valid for:"},{t:"ul",items:["60 months, if the holder is less than 40 years of age","24 months, once the holder has passed their 40th birthday","12 months, once the holder has passed their 50th birthday"]},{t:"p",x:"Older SACAA FAQ pages show shorter Class 2 periods. This practice follows the regulation. Medical conditions can mean a shorter period, so the date on your certificate is the one that counts. [How long is a Class 2 medical valid?](/blog/class-2-medical-validity-by-age/) explains how the date is counted and has a small expiry calculator."},{t:"h2",x:"How do I book with a designated examiner?",id:"examiner"},{t:"p",x:"A Class 2 renewal must be done by a Designated Aviation Medical Examiner (DAME). SACAA designates two kinds. Regular DAMEs may examine for and issue Class II and Class IV certificates. Senior DAMEs may also do Class I and Class III. Your family GP cannot issue a Class 2 certificate unless he or she is designated. Our guide to [SACAA medical examiners](/blog/sacaa-medical-examiners-dame/) shows how to check an examiner on the SACAA list."},{t:"p",x:"SACAA publishes the lists of Regular and Senior DAMEs on its aviation medicine page. It is worth checking that your examiner is on the current list."},{t:"p",x:"Dr A.O. Ndhlovu is listed by SACAA as a Regular DAME, number MR 336, at Grand Central Airport, Gate 2, Midrand. Class 2 renewals are within his scope. ClinoTrend does not currently issue Class 1."},{t:"h3",x:"When to book"},{t:"p",x:"Book a few weeks before your expiry date. That leaves time to get a specialist letter or an extra test if the examiner asks for one, without being grounded while you wait. Keep in mind that the new certificate runs from the month it is issued, so renewing many months early does not add the unused time to the new certificate."},{t:"h2",x:"What should I bring?",id:"documents"},{t:"p",x:"Regulation 67.00.7 says that when you attend the examination you must show proof of identity, show your licence and your latest medical certificate if you hold one, give the examiner information about your medical history, and sign a declaration that the information on the examination form is accurate, complete and true. In practice, bring:"},{t:"ul",items:["Your South African ID, driving licence or passport","Your pilot licence and your current medical certificate","Your logbook","A list of every medicine you take, including over the counter medicines","Glasses, contact lenses or hearing aids, if you use them","Recent reports from your doctor or specialist if you have a medical condition"]},{t:"p",x:"Complete the SACAA application form for a medical certificate online before you arrive. It is emailed only to the practice. The [Aviation Medical Report form, CA 67-02(a)](https://caasanwebsitestorage.blob.core.windows.net/aviation-medicine-forms-and-checklist/CA%2067-02%28a%29.pdf) is completed on the day."},{t:"h2",x:"What happens at the examination?",id:"examination"},{t:"p",x:"The examiner takes your medical history and examines you. At ClinoTrend a resting ECG, vision testing, a hearing test (audiometry) and urine screening are done on site. The examiner will tell you which other tests apply, including whether a chest X-ray or any further tests are needed, and whether they are done on site or referred. Ask the practice how long to allow when you book."},{t:"p",x:"Aviation medicals start from R1,500. Extra tests or reports are added only if the doctor finds they are needed during the medical. We confirm the fee when you book."},{t:"h2",x:"When do I receive my certificate?",id:"certificate"},{t:"p",x:"If you meet the standards and no further reports are needed, the certificate can be issued at the end of the examination. SACAA procedure AM007 describes two copies with the same serial number: the yellow copy goes to the SACAA licensing department and you keep the white copy with you while flying. Medical restrictions, if any apply, are written on the certificate."},{t:"p",x:"If more information is needed, your assessment is deferred until it arrives. Complicated cases are referred to the SACAA Aeromedical Committee, which AM007 says meets on the third Tuesday of each month, with documents due seven days before the meeting. If you disagree with a decision, Part 67 allows an appeal to the Director of Civil Aviation within 30 days. Read [what happens if a medical is deferred](/blog/aviation-medical-deferred-what-next/) for the full process."},{t:"h2",x:"What if I am running out of time?",id:"extension"},{t:"p",x:"Part 67, regulation 67.00.6(6), says you must apply for an extension **at least 15 days before your certificate expires**, and that the Director may extend it, on conditions, for **no more than 30 days**. SACAA procedure AM007 also says you must contact the SACAA medical department before the certificate expires, and SACAA's FAQ page explains where to send the request. An extension is a safety net, not a plan, so book your renewal early."},{t:"h2",x:"Where can I renew at Grand Central Airport?",id:"midrand"},{t:"p",x:"ClinoTrend Health & Aviation is at Gate 2, Office TG6B, Grand Central Airport, Midrand. [Book a Class 2 or Class 4 renewal](/book/?service=renewal), or read more on the [aviation medicals page](/aviation-medicals/) and the [Midrand aviation medical guide](/blog/aviation-medical-midrand-johannesburg/)."},{t:"cta",x:"Book your Class 2 renewal"}],faq:[{q:"Can my GP renew my Class 2 medical?",a:"Only if your GP is a SACAA Designated Aviation Medical Examiner. A Class 2 certificate must be issued by a DAME. Regular DAMEs issue Class 2 and Class 4. Senior DAMEs also issue Class 1 and Class 3."},{q:"How early can I renew my Class 2 medical?",a:"You can renew before the expiry date, but the new certificate runs from the month it is issued. Unused time on the old certificate is not added. Booking a few weeks early leaves room if a further report is needed."},{q:"What if my Class 2 medical expires before I can be examined?",a:"Contact the SACAA medical department before the expiry date to ask for an extension, as SACAA procedure AM007 requires. Regulation 67.00.6(6) says to apply at least 15 days before expiry, and an extension is for no more than 30 days. Then book your examination as soon as you can."},{q:"Do I need a chest X-ray for a Class 2 renewal?",a:"SACAA lists a chest X-ray at the initial examination and afterwards only when it is indicated on clinical grounds. The examiner will tell you which tests apply, including whether a chest X-ray is needed and whether it is done on site or referred."},{q:"Does a Class 1 medical cover Class 2 privileges?",a:"Yes. Regulation 67.00.2 says that a flight crew member with a valid Class 1 certificate is deemed to hold valid Class 2 and Class 4 certificates. ClinoTrend does not currently issue Class 1."}],sources:[e.validityReg,e.protocols,e.classes,e.application,e.am007,e.avmed,e.register,e.form,e.faq]},t={slug:"cabin-crew-medical-class-4-south-africa",title:"Cabin Crew Medical Requirements in SA | ClinoTrend",h1:"Cabin crew medical requirements in South Africa",description:"What medical cabin crew need in South Africa, who can examine you, Class 2 or Class 4, what to bring, and how to book at Grand Central Airport, Midrand.",excerpt:"What medical class cabin crew need, who can examine you, how long a certificate lasts, what to bring, and how to book at Grand Central Airport, Midrand.",keyword:"cabin crew medical south africa",question:"What medical do cabin crew need in South Africa?",answer:"Cabin crew need a Part 67 medical. The amended regulations list cabin crew under Class 4, while some SACAA pages still list Class 2. ClinoTrend can issue Class 2 or Class 4 for cabin crew, depending on what the airline or operator asks for. Tell us which class is required when you book.",facts:["Amended Part 67, regulation 67.00.2, lists the cabin crew member licence under Class 4.","Some SACAA pages, including the aviation medicine page and a medical-requirements table in the frequently asked questions, still list Class 2 or Class II for cabin crew.","Class 4 holders must also submit a yearly medical declaration to SACAA, on the form prescribed in SA-CATS 67 (regulation 67.00.9(3))."],secondary:["cabin crew class 4 medical","cabin crew medical certificate sacaa","class 4 aviation medical"],published:"2026-11-10",updated:"2026-11-10",status:"approved",tag:"Cabin crew",body:[{t:"p",x:"If you are starting a cabin crew course, joining an airline, or renewing an existing cabin crew medical, you need a current medical certificate under Part 67 of the Civil Aviation Regulations. Official sources do not all use the same class name, so it helps to know what your airline or operator has asked for before you book."},{t:"h2",x:"Which medical class do cabin crew need?",id:"class"},{t:"p",x:"The amended Part 67 regulation 67.00.2 lists the **cabin crew member licence under Class 4**, alongside recreational licences such as microlight, gyroplane and glider. A SACAA frequently asked questions item says the regulation was promulgated in May 2019 and that cabin crew require a Class 4 medical."},{t:"p",x:"Some SACAA pages still list cabin crew under **Class 2 or Class II**, including the aviation medicine page and the medical-requirements table in the frequently asked questions. Because those pages have not all been updated to match the amended regulation, tell us which class your airline or operator has asked for when you book."},{t:"p",x:"Dr A.O. Ndhlovu at ClinoTrend is a Regular DAME (SACAA MR 336). He can issue **Class 2 or Class 4** for cabin crew, depending on what is required. Our guide to [SACAA medical classes](/blog/sacaa-medical-classes-explained/) sets out who needs which class."},{t:"h2",x:"Who can do a cabin crew medical?",id:"who"},{t:"p",x:"If a Class 4 medical is required, it is the one class that does not have to be done by a designated examiner. Regulation 67.00.5 allows any medical practitioner registered with the HPCSA to perform the examination, provided the application, supporting reports and test results are sent to the designated body within 60 days for verification before the certificate is issued."},{t:"p",x:"A SACAA Designated Aviation Medical Examiner (DAME) can also examine you and issue a Class 4 certificate. Regular and Senior DAMEs are both authorised for Class IV. A Class 2 medical, if that is what is required, must be done by a DAME. Dr Ndhlovu can do either class at Grand Central Airport in Midrand."},{t:"h2",x:"What does the cabin crew medical include?",id:"tests"},{t:"p",x:"The examiner takes your medical history and examines you. Typical parts of the examination include:"},{t:"ul",items:["Your medical history, taken on the SACAA form CA 67-02(a), and a signed declaration","A physical examination","Vision testing","A hearing test (audiometry)","A resting ECG","Urine screening"]},{t:"p",x:"At ClinoTrend the ECG, vision testing, hearing test and urine screening are done on site. The examiner will tell you which other tests apply, including whether a chest X-ray or any further tests are needed, and whether they are done on site or referred. Height and swimming tests, if an airline requires them for training or employment, are not part of the SACAA medical itself."},{t:"h2",x:"How long does a cabin crew medical last?",id:"validity"},{t:"p",x:"If you are issued a **Class 4** certificate, regulation 67.00.6(4) sets the period at 60 months if you are less than 40 years of age, and 36 months if you are 40 or older, calculated to the last day of a month. If you are issued a **Class 2** certificate, regulation 67.00.6(3) sets 60 months if you are less than 40, 24 months after your 40th birthday, and 12 months after your 50th birthday. Medical conditions can mean a shorter period. [How long is a Class 2 medical valid?](/blog/class-2-medical-validity-by-age/) includes a calculator for both classes."},{t:"h3",x:"The yearly Class 4 declaration"},{t:"p",x:"If you hold a Class 4 certificate, regulation 67.00.9(3) requires you to complete and submit a medical declaration to SACAA **every year**, on the form prescribed in SA-CATS 67. Contact the practice or SACAA if you are unsure which form to use."},{t:"h2",x:"Should I get the medical before a cabin crew course?",id:"course"},{t:"p",x:"Yes, if the school or airline asks you to hold a current medical before you start, or before you fly as part of training. Completing it early means a finding that needs a further report will not delay the start of your course. Ask the school which class it wants you to book."},{t:"h2",x:"What should cabin crew bring?",id:"bring"},{t:"p",x:"Regulation 67.00.7 requires you to show proof of identity, your licence and your latest medical certificate if you have one, give your medical history and sign a declaration. Bring:"},{t:"ul",items:["Your South African ID or passport","Your cabin crew licence, if you already hold one, and your current medical certificate","A list of every medicine you take, including over the counter medicines","Glasses, contact lenses or hearing aids, if you use them","Recent reports from your doctor or specialist if you have a medical condition"]},{t:"p",x:"Complete the SACAA application form for a medical certificate online before you arrive. The [Aviation Medical Report form, CA 67-02(a)](https://caasanwebsitestorage.blob.core.windows.net/aviation-medicine-forms-and-checklist/CA%2067-02%28a%29.pdf) is completed on the day."},{t:"h2",x:"How do I book a cabin crew medical in Midrand?",id:"book"},{t:"p",x:"ClinoTrend Health & Aviation is in the Main Terminal Building at Grand Central Airport, Gate 2, Office TG6B, between Johannesburg and Pretoria. You can reach the airport from Midrand Gautrain Station by e-hailing or taxi; contact the practice for directions. Ask the practice how long to allow when you book. Aviation medicals start from R1,500. Extra tests or reports are added only if the doctor finds they are needed during the medical. We confirm the fee when you book."},{t:"p",x:"[Book a Class 4 medical](/book/?service=class-4) or a [Class 2 medical](/book/?service=class-2), or read more on the [aviation medicals page](/aviation-medicals/)."},{t:"cta",x:"Book your cabin crew medical"}],faq:[{q:"Do cabin crew need a Class 2 or a Class 4 medical?",a:"It depends on what the airline or operator asks for. Amended Part 67 lists cabin crew under Class 4. Some SACAA pages still list Class 2 or Class II. ClinoTrend can issue Class 2 or Class 4 for cabin crew. Tell us which class is required when you book."},{q:"Can my own GP do my cabin crew medical?",a:"If a Class 4 medical is required, regulation 67.00.5 allows a medical practitioner registered with the HPCSA to perform the examination, provided the results are sent for verification within 60 days. A Class 2 medical must be done by a designated aviation medical examiner. A DAME can also issue Class 4."},{q:"How long is a Class 4 medical valid for cabin crew?",a:"Under regulation 67.00.6(4), a Class 4 certificate is valid for 60 months if you are less than 40 years of age, and 36 months if you are 40 or older, to the last day of a month. If you are issued a Class 2 certificate instead, different periods apply under regulation 67.00.6(3)."},{q:"Do I need the medical before my cabin crew course?",a:"If the school or airline requires a current medical before you start, or before you fly in training, complete it first. Ask which class they want you to book."},{q:"Are height and swimming part of the medical?",a:"No. Height and swimming requirements, if an airline or school uses them, are training or employment conditions, not part of the SACAA medical examination itself."}],sources:[e.cabin,e.classes,e.faq,e.class4,e.duties,e.validityReg,e.protocols,e.avmed,e.register,e.form]},s={slug:"aviation-medical-midrand-johannesburg",title:"Aviation Medical Examiner, Johannesburg | ClinoTrend",h1:"Aviation medical examiner in Midrand and Johannesburg",description:"Find a SACAA aviation medical examiner in Midrand and Johannesburg: what to bring, how the exam works, fees from R1,500, and how to book at Grand Central.",excerpt:"Where to find a SACAA designated examiner in Midrand, what to bring, how the examination works, fees, and how to book at Grand Central Airport.",keyword:"aviation medical examiner johannesburg",question:"Where can I get an aviation medical near Johannesburg?",answer:"Dr A.O. Ndhlovu, a SACAA Regular Designated Aviation Medical Examiner (MR 336), does Class 2 and Class 4 aviation medicals at ClinoTrend, Gate 2, Grand Central Airport in Midrand, on the N1 between Johannesburg and Pretoria. Book online, or fly in to FAGC. ClinoTrend does not currently issue Class 1 or Class 3.",facts:["Aviation medicals start from R1,500. Extra tests or reports are added only if the doctor finds they are needed during the medical. We confirm the fee when you book.","On-site tests include a resting ECG, vision testing, audiometry (hearing) and urine screening.","You can reach Grand Central from Midrand Gautrain Station by e-hailing or taxi. Contact the practice for directions."],secondary:["aviation medical midrand","sacaa medical examiner johannesburg","class 2 medical midrand"],published:"2026-11-10",updated:"2026-11-10",status:"approved",tag:"Midrand",body:[{t:"p",x:"If you are looking for a SACAA aviation medical examiner in Midrand or Johannesburg, ClinoTrend Health & Aviation is at Grand Central Airport, between Johannesburg and Pretoria. Dr A.O. Ndhlovu is listed on the SACAA list of Regular Designated Aviation Medical Examiners as MR 336."},{t:"h2",x:"Which medicals are done at Grand Central?",id:"which"},{t:"p",x:"As a Regular DAME, Dr Ndhlovu issues Class 2 and Class 4 medical certificates. That covers student and private pilots, recreational pilots, and cabin crew (Class 2 or Class 4, depending on what the airline or operator asks for). Our guides to [SACAA medical classes](/blog/sacaa-medical-classes-explained/) and [cabin crew medical requirements](/blog/cabin-crew-medical-class-4-south-africa/) explain who needs which class."},{t:"table",caption:"Medical classes at ClinoTrend (Grand Central Airport, Midrand)",head:["Class","Typical licences","Issued here?"],rows:[["Class 2","Student pilots (SPL) and private pilots (PPL), plus other licences listed in regulation 67.00.2","Yes"],["Class 4","Recreational pilots, and cabin crew when a Class 4 is required","Yes"],["Class 1","Commercial and airline transport pilots","Not currently"],["Class 3","Air traffic controllers","Not currently"]]},{t:"p",x:"Class 1 and Class 3 medicals need a SACAA Senior DAME. ClinoTrend does not currently issue Class 1 or Class 3."},{t:"h2",x:"Where is the practice?",id:"where"},{t:"p",x:"ClinoTrend is in the Main Terminal Building, Gate 2, Office TG6B, Grand Central Airport, 3 New Road, Midrand. You can drive in, or fly in to FAGC and park on the apron outside the Gate 2 terminal doors."},{t:"ul",items:["**By car:** Grand Central Airport is on the N1 between Johannesburg and Pretoria. Use Gate 2.","**By Gautrain:** You can reach Grand Central from Midrand Gautrain Station by e-hailing or taxi. Contact the practice for directions.","**By air:** Fly in to Grand Central (FAGC) and park on the apron outside the terminal doors."]},{t:"p",x:"The [contact page](/contact/) has hours, a map and further directions."},{t:"h2",x:"What should I bring?",id:"bring"},{t:"p",x:"Part 67 (regulation 67.00.7) requires you to show proof of identity, your licence and your latest medical certificate if you have one, give your medical history and sign a declaration. Bring:"},{t:"ul",items:["Your South African ID or passport","Any aviation licence you hold, and your logbook if you are renewing","Your most recent aviation medical certificate, if you have one","A list of every medicine you take, including over the counter medicines","Glasses, contact lenses or hearing aids, if you use them","Recent reports from your doctor or specialist if you have a medical condition"]},{t:"p",x:"Complete the SACAA application form for a medical certificate online before you arrive. The [Aviation Medical Report form, CA 67-02(a)](https://caasanwebsitestorage.blob.core.windows.net/aviation-medicine-forms-and-checklist/CA%2067-02%28a%29.pdf) is completed on the day."},{t:"h2",x:"What happens during the examination?",id:"examination"},{t:"p",x:"The examiner takes your history and examines you. At ClinoTrend a resting ECG, vision testing, a hearing test (audiometry) and urine screening are done on site. The examiner will tell you which other tests apply, including whether a chest X-ray or any further tests are needed, and whether they are done on site or referred. Ask the practice how long to allow when you book, and whether you should arrive early to complete paperwork."},{t:"h2",x:"What does an aviation medical cost?",id:"fees"},{t:"p",x:"Aviation medicals start from R1,500. Extra tests or reports are added only if the doctor finds they are needed during the medical. We confirm the fee when you book. Fees differ between examiners and are set by each practice."},{t:"h2",x:"How do I book?",id:"book"},{t:"p",x:"Medicals are by appointment only. [Book an appointment](/book/), choose a [Class 2 medical](/book/?service=class-2), a [Class 4 medical](/book/?service=class-4), or a [renewal](/book/?service=renewal), or read the [aviation medicals page](/aviation-medicals/). Flight schools, academies and airlines can arrange group bookings in advance."},{t:"cta",x:"Book your aviation medical in Midrand"}],faq:[{q:"Where can I get an aviation medical near Johannesburg?",a:"At ClinoTrend Health & Aviation, Gate 2, Grand Central Airport, Midrand, with Dr A.O. Ndhlovu, a SACAA Regular Designated Aviation Medical Examiner (MR 336). The practice does Class 2 and Class 4 medicals."},{q:"How long does an aviation medical take?",a:"Ask the practice how long to allow when you book, and arrive a little early. Bringing the documents on the checklist and completing the SACAA form online beforehand helps the visit run smoothly."},{q:"How much does an aviation medical cost in Midrand?",a:"Aviation medicals start from R1,500. Extra tests or reports are added only if the doctor finds they are needed during the medical. We confirm the fee when you book."},{q:"Can I do a Class 1 medical at ClinoTrend?",a:"ClinoTrend does not currently issue Class 1. Class 1 and Class 3 medicals need a SACAA Senior DAME."},{q:"Can I fly in to Grand Central for my medical?",a:"Yes. Fly in to Grand Central Airport (FAGC) and park on the apron outside the Gate 2 terminal doors. Book first, as medicals are by appointment only."}],sources:[e.register,e.avmed,e.classes,e.application,e.form,e.faq]},o={slug:"class-2-medical-validity-by-age",title:"How Long a Class 2 Medical Is Valid | ClinoTrend",h1:"How long a Class 2 medical is valid, by age",description:"How long a SACAA Class 2 medical is valid: 60 months under 40, 24 months from 40, 12 months from 50, under Part 67. Includes Class 4 periods and a calculator.",excerpt:"Class 2 validity under Part 67: 60 months under 40, 24 months after 40, 12 months after 50. Class 4 periods, how the date is counted, and a calculator.",keyword:"class 2 medical validity",question:"How long is a SACAA Class 2 medical valid?",answer:"Under Part 67, regulation 67.00.6(3), a Class 2 medical is valid for 60 months if you are less than 40, 24 months after your 40th birthday, and 12 months after your 50th birthday, running to the last day of a month. Older FAQ pages show shorter periods; this practice follows the regulation. The date on your certificate counts.",facts:["A Class 4 certificate is valid for 60 months if you are less than 40, and 36 months from age 40, under regulation 67.00.6(4).","A DAME or a SACAA medical assessor may shorten the period and endorse a limitation, under regulation 67.00.6(5).","Unused time is not carried over when you renew: the new certificate runs from the month it is issued."],secondary:["class 2 medical certificate validity south africa","class 4 medical validity","sacaa medical expiry"],published:"2026-11-10",updated:"2026-11-10",status:"approved",tag:"Validity",body:[{t:"p",x:"The date on your medical certificate is the date that matters. The periods below come from Part 67, regulation 67.00.6, and from the SACAA summarised medical protocols (effective 16 November 2021). Older SACAA FAQ pages show shorter Class 2 periods. This practice follows the regulation."},{t:"h2",x:"How long is a Class 2 medical valid?",id:"class-2"},{t:"p",x:"Regulation 67.00.6(3) says a Class 2 certificate is valid for:"},{t:"ul",items:["60 months, if the holder is less than 40 years of age","24 months, once the holder has passed their 40th birthday","12 months, once the holder has passed their 50th birthday"]},{t:"p",x:"The period is calculated from the last day of the calendar month in which the certificate is issued. For example, a Class 2 issued on 10 March 2026 to a holder younger than 40 expires on 31 March 2031. The same issue date expires on 31 March 2028 after the 40th birthday, and on 31 March 2027 after the 50th birthday."},{t:"h2",x:"How is the expiry date counted?",id:"counted"},{t:"p",x:"Validity always runs to the last day of a month. If a certificate is issued part way through a month, that whole month is counted, and the period then runs in calendar months from the end of that month. Medical conditions can mean more frequent examinations, so always use the date printed on your certificate."},{t:"calc"},{t:"h2",x:"How long is a Class 4 medical valid?",id:"class-4"},{t:"p",x:"Regulation 67.00.6(4) says a Class 4 certificate is issued for a period not exceeding 60 calendar months if the applicant is less than 40 years of age, and 36 calendar months if the applicant is 40 years of age or more, again to the last day of the month. Cabin crew may be issued Class 2 or Class 4; use the periods that match the class on your certificate. See [cabin crew medical requirements](/blog/cabin-crew-medical-class-4-south-africa/)."},{t:"h2",x:"What about Class 1 and Class 3?",id:"other-classes"},{t:"p",x:"Class 1 periods are set out in regulation 67.00.6(1). In short, a Class 1 certificate is issued for 12 months if the applicant is less than 40. From age 40 the period depends on the licence and the type of operation: six months for an airline transport pilot in single-crew commercial air transport operations; 12 months for an airline transport pilot in multi-crew operations, and for a commercial pilot, until age 60; and six months from age 60 for those last two groups. Holders in the 12 month bands from age 40 may also have extra reporting duties under regulation 67.00.6(2)."},{t:"p",x:"Class 3, under regulation 67.00.6(3), is 48 months if the holder is less than 40, 24 months after the 40th birthday, and 12 months after the 50th birthday. Class 1 and Class 3 medicals need a SACAA Senior DAME. ClinoTrend does not currently issue Class 1 or Class 3."},{t:"h2",x:"Can the period be shorter?",id:"shorter"},{t:"p",x:"Yes. Regulation 67.00.6(5) allows a DAME or a medical assessor to reduce the period of validity and endorse the reason, or any limitation, if a further examination or test is needed, or if safe performance of the holder's duties depends on a shorter period or a special limitation."},{t:"h2",x:"What changes when I turn 40 or 50?",id:"birthdays"},{t:"p",x:"The Class 2 period is set by your age on the date the certificate is issued. Once you have passed your 40th birthday, a new Class 2 is issued for 24 months. Once you have passed your 50th birthday, a new Class 2 is issued for 12 months. Turning 40 or 50 during a current period does not cut that certificate short; the shorter period applies at the next issue."},{t:"h2",x:"How should I plan renewals?",id:"planning"},{t:"p",x:"Book a few weeks before the expiry date, so there is time if the examiner asks for a specialist letter or an extra test. Renewing many months early does not add the unused time to the new certificate, because the new period starts from the month of issue. Our [Class 2 renewal guide](/blog/renew-sacaa-class-2-medical/) walks through the steps."},{t:"h2",x:"What if I am close to expiry?",id:"expiry"},{t:"p",x:"Regulation 67.00.6(6) says you must apply for an extension at least 15 days before your certificate expires. The Director may extend it, on conditions, for no more than 30 days. SACAA procedure AM007 also says you must contact the SACAA medical department before the certificate expires. An extension is a safety net, not a plan."},{t:"cta",x:"Book your Class 2 or Class 4 renewal"}],faq:[{q:"How long is a Class 2 medical valid if I am under 40?",a:"60 months, calculated from the last day of the month in which the certificate is issued, under regulation 67.00.6(3). Medical conditions can mean a shorter period. The date on your certificate is the one that applies."},{q:"How long is a Class 2 medical valid after 40?",a:"24 months once you have passed your 40th birthday, and 12 months once you have passed your 50th birthday, under regulation 67.00.6(3). Older SACAA FAQ pages show shorter periods; this practice follows the regulation."},{q:"How long is a Class 4 medical valid?",a:"60 months if you are less than 40 years of age, and 36 months if you are 40 or older, under regulation 67.00.6(4), to the last day of a month."},{q:"Can my certificate be valid for a shorter time?",a:"Yes. Regulation 67.00.6(5) allows a DAME or a medical assessor to reduce the period and endorse a reason or a limitation when a further test is needed, or when safety depends on it."},{q:"Can I extend my medical certificate?",a:"Yes, by applying to SACAA at least 15 days before expiry. Regulation 67.00.6(6) allows an extension of no more than 30 days, on conditions. Contact the SACAA medical department before the certificate expires."}],sources:[e.validityReg,e.protocols,e.am007,e.classes,e.faq,e.avmed]},n={slug:"sacaa-medical-classes-explained",title:"Aviation Medical Classes in South Africa | ClinoTrend",h1:"SACAA aviation medical classes explained",description:"Which SACAA medical class you need: Class 1, 2, 3, 4 and 5 under Part 67, who may examine you, and which classes ClinoTrend issues in Midrand.",excerpt:"Class 1 to Class 5 under Part 67: which licences they cover, who may examine you, and which classes are issued at ClinoTrend in Midrand.",keyword:"sacaa medical classes",question:"Which SACAA medical class do I need?",answer:"It depends on your licence. Under Part 67, regulation 67.00.2, commercial and airline pilots need Class 1, student and private pilots Class 2, air traffic services staff Class 3, most recreational pilots Class 4, and paragliding, hang gliding and parachute licences a Class 5 declaration. ClinoTrend issues Class 2 and Class 4.",facts:["A flight crew member with a valid Class 1 certificate is deemed to hold valid Class 2 and Class 4 certificates (regulation 67.00.2(2)).","Regular DAMEs issue Class II and Class IV. Senior DAMEs also issue Class I and Class III, as described on the SACAA aviation medicine page.","ClinoTrend does not currently issue Class 1 or Class 3."],secondary:["class 1 medical south africa","class 2 vs class 4 medical","class 5 medical sacaa"],published:"2026-11-10",updated:"2026-11-10",status:"approved",tag:"Classes",body:[{t:"p",x:"South African aviation licences are tied to a class of medical certificate under Part 67 of the Civil Aviation Regulations. The class you need is set by your licence, not by a preference. This guide follows regulation 67.00.2 for which licences sit under each class, and official SACAA wording for who may examine you."},{t:"h2",x:"What are the five SACAA medical classes?",id:"five"},{t:"table",caption:"SACAA medical classes (Part 67, regulation 67.00.2, as amended)",head:["Class","Main licences it covers","Who examines"],rows:[["Class 1","Airline transport pilot (ATPL), commercial pilot (CPL) for aeroplane, airship and helicopter, instrument rating, Class I test pilot rating","Senior DAME"],["Class 2","Student pilot (SPL), private pilot (PPL) for aeroplane, airship and helicopter, flight engineer, free balloon CPL, commercial glider pilot","Regular or Senior DAME"],["Class 3","Air traffic controller (ATC), air traffic service assistant, remote pilot (RPL)","Senior DAME"],["Class 4","Cabin crew member licence, and recreational licences such as microlight, gyroplane, glider and free balloon","Regular or Senior DAME, or a registered medical practitioner under regulation 67.00.5"],["Class 5","Paraglider, hang glider, powered paratrike and parachute licences and their student licences","Registered medical practitioner (declaration sent to SACAA)"]]},{t:"p",x:'The table shortens the lists. The full wording is in the [SACAA copy of regulation 67.00.2](https://caasanwebsitestorage.blob.core.windows.net/aviation-medicine-general-information/Ammended%20%20Part%2067%20Regulations%20Classes%20of%20medical%20certificates.pdf), which also lists instructor ratings, tandem licences and test pilot ratings. The "Who examines" column follows the SACAA aviation medicine page (Regular DAME: Class II and IV; Senior DAME: Class I to IV), together with regulation 67.00.5 for Class 4 and regulation 67.00.2(8) and (9) for Class 5.'},{t:"h2",x:"What is the difference between a Class 1 and a Class 2 medical?",id:"class1-class2"},{t:"p",x:"A Class 1 is for flying as a profession: the CPL, the ATPL and the instrument rating. A Class 2 is for the student and private pilot licences, among others. Class 1 examinations must be done by a SACAA **Senior** Designated Aviation Medical Examiner (DAME). Validity periods also differ; see [how long a Class 2 medical is valid](/blog/class-2-medical-validity-by-age/), which also summarises Class 1 periods under regulation 67.00.6(1)."},{t:"p",x:"Regulation 67.00.2(2) adds a useful rule: a flight crew member with a valid Class 1 certificate is deemed to hold valid Class 2 and Class 4 certificates. If you stop flying commercially, regulation 67.00.2(4) lets you ask for an expired Class 1 to be substituted by a Class 2 or Class 4, with the remaining validity worked out under regulation 67.00.6. ClinoTrend does not currently issue Class 1."},{t:"h2",x:"Which class do cabin crew need?",id:"cabin"},{t:"p",x:"Amended regulation 67.00.2 lists the cabin crew member licence under **Class 4**. Some SACAA pages, including the aviation medicine page and a medical-requirements table in the frequently asked questions, still list cabin crew under Class 2 or Class II. ClinoTrend can issue Class 2 or Class 4 for cabin crew, depending on what the airline or operator asks for. Tell us which class is required when you book. The [cabin crew medical guide](/blog/cabin-crew-medical-class-4-south-africa/) explains this in more detail."},{t:"h2",x:"Which class do recreational pilots need?",id:"recreational"},{t:"p",x:"Most recreational licences, including microlight, gyroplane, glider, light sport aeroplane and free balloon, sit under **Class 4**. Paragliding, hang gliding, powered paratrike and parachute licences, and their student licences, sit under **Class 5**."},{t:"h2",x:"What is a Class 5 medical?",id:"class5"},{t:"p",x:"Class 5 is a declaration sent to SACAA, signed by a registered medical practitioner. Under regulation 67.00.2(8), a person under 60 years of age who submits a duly completed Class 5 medical self-declaration, on the prescribed form and signed by a medical practitioner registered under the Health Professions Act, is deemed to hold a Class 5 medical certificate. Under regulation 67.00.2(9), from age 60 the form is the medical declaration prescribed for that age, also signed by a registered medical practitioner."},{t:"h2",x:"Who can examine you for each class?",id:"who"},{t:"p",x:"SACAA's aviation medicine page states that Regular DAMEs may do Class II and Class IV, and Senior DAMEs may do Class I, II, III and IV. Class 4 may also be done by a registered medical practitioner under regulation 67.00.5, subject to verification. Class 5 is the declaration described above, signed by a registered medical practitioner. Our guide to [checking a SACAA medical examiner](/blog/sacaa-medical-examiners-dame/) shows how to use the official lists. Dr A.O. Ndhlovu is a Regular DAME (MR 336) and issues Class 2 and Class 4 at Grand Central Airport, Midrand. ClinoTrend does not currently issue Class 1 or Class 3."},{t:"h2",x:"How long is each certificate valid?",id:"validity"},{t:"p",x:"Validity periods are set in regulation 67.00.6 and depend on the class and your age. This page does not repeat every figure. [How long is a Class 2 medical valid?](/blog/class-2-medical-validity-by-age/) sets out Class 2 and Class 4, summarises Class 1 and Class 3, and includes a calculator. A DAME or a medical assessor may also shorten the period under regulation 67.00.6(5)."},{t:"h2",x:"Not sure which class you need?",id:"book"},{t:"p",x:"Check the licence you hold or are training for against regulation 67.00.2, or ask your flight school or operator. Then [book the matching medical](/book/), or start from the [aviation medicals page](/aviation-medicals/)."},{t:"cta",x:"Book a Class 2 or Class 4 medical"}],faq:[{q:"Do private pilots need a Class 1 or a Class 2 medical?",a:"A Class 2. Regulation 67.00.2 lists the student pilot licence and the private pilot licence for aeroplane, airship and helicopter under Class 2."},{q:"Does a Class 1 medical cover Class 2?",a:"Yes. Regulation 67.00.2(2) says a flight crew member with a valid Class 1 certificate is deemed to hold valid Class 2 and Class 4 certificates."},{q:"Which medical class do air traffic controllers need?",a:"Class 3. It also covers air traffic service assistants and remote pilots (RPL). Class 3 medicals are done by a SACAA Senior DAME."},{q:"Can a Regular DAME do a Class 1 medical?",a:"No. A Regular DAME does Class II and Class IV. Class I and Class III need a Senior DAME. ClinoTrend does not currently issue Class 1 or Class 3."},{q:"What is a Class 5 medical?",a:"A declaration sent to SACAA, signed by a registered medical practitioner, for paragliding, hang gliding, powered paratrike and parachute licences. For applicants under 60 the prescribed form is the Class 5 medical self-declaration. From age 60 the form is the medical declaration prescribed for that age."}],sources:[e.classes,e.classesReg,e.class4,e.validityReg,e.avmed,e.register]},r={slug:"student-pilot-medical-south-africa",title:"Student Pilot Medical Requirements | ClinoTrend",h1:"Student pilot medical requirements in South Africa",description:"What medical a student pilot needs in South Africa before flying solo, when to book, what to bring, and how schools can arrange group medicals in Midrand.",excerpt:"The medical a student pilot needs before flying solo, when to book, what to bring, and how flight schools can arrange group medicals in Midrand.",keyword:"student pilot medical south africa",question:"What medical does a student pilot need in South Africa?",answer:"Before you fly solo on a student pilot licence you need a valid medical certificate issued under Part 67. An SPL for aeroplane, airship or helicopter sits under Class 2. Recreational student licences sit under Class 4. Book a few weeks before you expect to fly solo, and complete the SACAA application form beforehand.",facts:["Part 61, regulation 61.02.1, says an applicant for an SPL or ISPL must be 15 years or older, hold a valid medical certificate issued under Part 67, and be registered with an approved training organisation.","Aviation medicals start from R1,500. Extra tests or reports are added only if the doctor finds they are needed during the medical. We confirm the fee when you book.","Flight schools can arrange group medicals at ClinoTrend in advance."],secondary:["student pilot licence medical","first class 2 medical","flight school aviation medical"],published:"2026-11-10",updated:"2026-11-10",status:"approved",tag:"Student pilots",body:[{t:"p",x:"A first aviation medical is one of the early steps in learning to fly. This guide covers what a student pilot needs, when to book, what happens at a first Class 2 medical, and how flight schools can book a group at Grand Central Airport, Midrand."},{t:"h2",x:"Do student pilots need a medical?",id:"need"},{t:"p",x:"Yes. Part 61, regulation 61.02.1 (as amended on 21 August 2026), says an applicant for a student pilot licence (SPL) or integrated student pilot licence (ISPL) must be 15 years or older, hold a valid medical certificate issued in terms of Part 67, and be registered with an approved training organisation (ATO). Your SPL is what allows you to fly solo under instruction, so the medical comes first."},{t:"h2",x:"Which medical class does a student pilot need?",id:"class"},{t:"p",x:"Regulation 67.00.2 lists the SPL under **Class 2**, alongside the private pilot licence (PPL). Students on recreational licences are different: an SPL for a microlight, gyroplane, light sport aeroplane or glider licence sits under **Class 4**. Our guide to [SACAA medical classes](/blog/sacaa-medical-classes-explained/) has the full list."},{t:"p",x:"The 21 August 2026 amendment added the integrated student pilot licence (ISPL). An ISPL, like an SPL, requires a valid medical certificate issued under Part 67. Confirm with your flight school, or contact the practice, which class is required for your course."},{t:"p",x:"A commercial pilot licence (CPL), an airline transport pilot licence (ATPL) and an instrument rating all need a **Class 1** medical, which only a SACAA Senior DAME may do. Ask your flight school when it wants you to hold a Class 1. Dr Ndhlovu is a Regular DAME, so at ClinoTrend we do the Class 2 that covers your SPL and PPL. ClinoTrend does not currently issue Class 1."},{t:"h2",x:"When should I book my first medical?",id:"when"},{t:"p",x:"Book a few weeks before you expect to fly solo, so there is time if the examiner asks for a further test or a report. You do not usually need the certificate before your first dual lessons, unless your school asks for it. Complete the SACAA application form online before you arrive."},{t:"h2",x:"What happens at a first Class 2 medical?",id:"first"},{t:"p",x:"You complete your medical history on the SACAA form and sign a declaration that it is accurate, complete and true, as regulation 67.00.7 requires. The doctor then examines you. At ClinoTrend these tests are done on site:"},{t:"ul",items:["A resting ECG","Vision testing","A hearing test (audiometry)","Urine screening"]},{t:"p",x:"The examiner will tell you which other tests apply for a first Class 2, including whether a chest X-ray or any further tests are needed, and whether they are done on site or referred. SACAA's medical requirements list a chest X-ray at the initial examination, and afterwards only when it is indicated on clinical grounds. Ask the practice how long to allow when you book."},{t:"h2",x:"How long is a student pilot medical valid?",id:"validity"},{t:"p",x:"If you are issued a Class 2 certificate and you are less than 40 years of age, regulation 67.00.6(3) sets the period at 60 months, to the last day of the month of issue. After 40 and after 50 the period is shorter. [How long is a Class 2 medical valid?](/blog/class-2-medical-validity-by-age/) explains the dates and has a calculator. Recreational students issued a Class 4 follow the Class 4 periods."},{t:"h2",x:"What should a student pilot bring?",id:"bring"},{t:"p",x:"Bring your South African ID or passport, a list of every medicine you take, glasses or contact lenses if you use them, and any reports from your own doctor if you have a medical condition. Complete the SACAA application form beforehand. The [Aviation Medical Report form, CA 67-02(a)](https://caasanwebsitestorage.blob.core.windows.net/aviation-medicine-forms-and-checklist/CA%2067-02%28a%29.pdf) is completed on the day."},{t:"p",x:"Students can start from 15. If you are under 18, contact the practice to confirm any extra requirements before you book."},{t:"h2",x:"Can flight schools book group medicals?",id:"groups"},{t:"p",x:"Yes. Flight schools can arrange group medicals at ClinoTrend in advance. Call or email the practice with the number of students and the dates that suit you. Aviation medicals start from R1,500. Extra tests or reports are added only if the doctor finds they are needed during the medical. We confirm the fee when you book. [Book a Class 2 medical](/book/?service=class-2), or read the [aviation medicals page](/aviation-medicals/)."},{t:"cta",x:"Book a student pilot medical"}],faq:[{q:"Do I need a medical before my first flying lesson?",a:"You need a valid medical certificate issued under Part 67 before you fly solo on a student pilot licence. Some schools also ask for it earlier. Check with your flight school."},{q:"What medical class is a student pilot licence?",a:"An SPL for aeroplane, airship or helicopter is listed under Class 2 in regulation 67.00.2. Recreational student licences such as microlight or glider sit under Class 4."},{q:"How old must I be for a student pilot licence?",a:"Regulation 61.02.1, as amended on 21 August 2026, says an applicant for an SPL or ISPL must be 15 years or older. If you are under 18, contact the practice to confirm any extra requirements before you book."},{q:"Can I do my Class 1 medical at ClinoTrend?",a:"ClinoTrend does not currently issue Class 1. A Class 1 needs a SACAA Senior DAME. Dr Ndhlovu is a Regular DAME and does Class 2 and Class 4 medicals."},{q:"Can a flight school book medicals for a group of students?",a:"Yes. Group bookings are arranged in advance. Contact the practice with the number of students and the dates that suit you."}],sources:[e.spl,e.classes,e.application,e.validityReg,e.protocols,e.form,e.avmed,e.register]},l={slug:"sacaa-medical-examiners-dame",title:"SACAA Medical Examiners: How to Check | ClinoTrend",h1:"SACAA medical examiners: how to check a DAME",description:"What a SACAA Designated Aviation Medical Examiner (DAME) is, Regular versus Senior, how to check the official list, and where to find one in Midrand.",excerpt:"What a DAME is, the difference between Regular and Senior examiners, how to check the official SACAA lists, and where to find one in Midrand.",keyword:"sacaa medical examiners",question:"How do I check that an aviation medical examiner is designated by SACAA?",answer:"A DAME is a doctor designated by the Director of Civil Aviation to examine applicants and to issue or defer certificates under Part 67. Regular DAMEs do Class 2 and Class 4. Senior DAMEs also do Class 1 and Class 3. Check the SACAA lists. Dr A.O. Ndhlovu is listed as Regular DAME MR 336 at Grand Central Airport, Midrand.",facts:["SACAA publishes separate lists of Regular and Senior Designated Aviation Medical Examiners on its aviation medicine page.","Your family GP cannot issue a Class 1, 2 or 3 certificate unless he or she is designated. Class 4 may be done by a registered medical practitioner under regulation 67.00.5.","Always match the examiner's designation to the class you need."],secondary:["designated aviation medical examiner","dame sacaa","aviation medical examiner midrand"],published:"2026-11-10",updated:"2026-11-10",status:"approved",tag:"Examiners",body:[{t:"p",x:"An aviation medical in South Africa has to be done by the right kind of examiner for the class you need. This guide explains what a Designated Aviation Medical Examiner is, how Regular and Senior designations differ, and how to check the official SACAA lists before you book."},{t:"h2",x:"What is a DAME?",id:"what"},{t:"p",x:"A Designated Aviation Medical Examiner, or DAME, is a doctor designated by the Director of Civil Aviation under Part 67, regulation 67.00.4, to do aviation medical examinations and to issue, or defer, medical certificates on behalf of SACAA. The designation is personal to that doctor and is shown by a designation number, such as MR 336."},{t:"h2",x:"What is the difference between a Regular DAME and a Senior DAME?",id:"difference"},{t:"p",x:"SACAA's aviation medicine page describes two categories:"},{t:"ul",items:["**Regular DAME:** authorised to examine for and issue Class II and Class IV medical certificates.","**Senior DAME:** authorised to examine for and issue Class I, II, III and IV medical certificates."]},{t:"p",x:"If you need a Class 1 or Class 3 medical, you must see a Senior DAME. A Regular DAME can renew a Class 2 or issue a Class 4. Our guide to [SACAA medical classes](/blog/sacaa-medical-classes-explained/) lists which licences sit under each class."},{t:"h2",x:"How do I check that an examiner is designated?",id:"check"},{t:"p",x:"SACAA publishes the names of designated examiners on its [aviation medicine page](https://www.caa.co.za/industry-information/aviation-medicine/). There is a list of Regular DAMEs and a list of Senior DAMEs. Look for the doctor's name, designation number and the town or practice address, and check that the list is the current one."},{t:"p",x:"A current designation matters because only a designated examiner may issue the classes they are authorised for. If you are unsure, contact the SACAA medical department or ask the practice to confirm the designation number against the list."},{t:"h2",x:"Can my own GP do the medical?",id:"gp"},{t:"p",x:"Not for Class 1, 2 or 3, unless your GP is also a designated examiner. Class 4 is different: regulation 67.00.5 allows a medical practitioner registered with the HPCSA to perform the examination, provided the application and results are sent for verification within 60 days before the certificate is issued. A DAME can also issue Class 4."},{t:"h2",x:"Where can I find a SACAA medical examiner in Midrand?",id:"midrand"},{t:"p",x:"Dr A.O. Ndhlovu is listed as a Regular DAME, designation MR 336, at ClinoTrend Health & Aviation, Gate 2, Grand Central Airport, Midrand. He does Class 2 and Class 4 medicals, including for cabin crew when either class is required. ClinoTrend does not currently issue Class 1 or Class 3. [Book an appointment](/book/), or read the [Midrand aviation medical guide](/blog/aviation-medical-midrand-johannesburg/) and the [aviation medicals page](/aviation-medicals/)."},{t:"cta",x:"Book with a designated examiner in Midrand"}],faq:[{q:"What does DAME stand for?",a:"Designated Aviation Medical Examiner. It is a doctor designated by the Director of Civil Aviation under Part 67 to examine applicants and to issue or defer medical certificates on behalf of SACAA."},{q:"Where is the list of SACAA medical examiners?",a:"On the SACAA aviation medicine page. SACAA publishes a list of Regular DAMEs and a list of Senior DAMEs. Check the current list for the doctor's name and designation number."},{q:"Can a Regular DAME renew my Class 2?",a:"Yes. Regular DAMEs are authorised for Class II and Class IV. Senior DAMEs may also do Class I and Class III."},{q:"Can my own GP do my aviation medical?",a:"Only if your GP is a designated examiner, except for Class 4, which regulation 67.00.5 allows a registered medical practitioner to perform, subject to verification. Class 1, 2 and 3 must be done by a DAME of the right category."},{q:"Is Dr Ndhlovu a SACAA designated examiner?",a:"Yes. He is listed on the SACAA list of Regular DAMEs as MR 336, at ClinoTrend, Grand Central Airport, Midrand. He does Class 2 and Class 4 medicals. ClinoTrend does not currently issue Class 1 or Class 3."}],sources:[e.register,e.avmed,e.designation,e.class4,e.am007,e.classes]},d={slug:"aviation-medical-deferred-what-next",title:"Aviation Medical Deferral: What Next | ClinoTrend",h1:"What happens if your aviation medical is deferred",description:"What happens if a SACAA aviation medical is deferred: next steps under Part 67, the Aeromedical Committee, limitations, the 30 day appeal, and what to report.",excerpt:"What a deferral means, how SACAA reviews a case, limitations and shorter validity, the 30 day appeal, and what you must report between medicals.",keyword:"aviation medical deferred",question:"What happens if my SACAA aviation medical is deferred?",answer:"A deferral is not a final no. Under Part 67 a designated examiner may defer your certificate until SACAA gives an instruction, usually after a further report or test. Complicated cases go to the SACAA Aeromedical Committee. A certificate can also be issued with a limitation or a shorter validity, and you may appeal a decision within 30 days.",facts:["Examination records may be used to issue a certificate for no more than 90 days (regulation 67.00.12). After that the examination may need to be repeated.","SACAA procedure AM007 says the Aeromedical Committee meets on the third Tuesday of each month, and documents must be submitted at least seven days before the meeting.","An appeal against a deferral or similar decision is 30 days; an appeal against a suspension is 14 days under regulation 67.00.14."],secondary:["sacaa aeromedical committee","medical certificate limitation","appeal aviation medical"],published:"2026-11-10",updated:"2026-11-10",status:"approved",tag:"Deferrals",body:[{t:"p",x:"Most aviation medicals end with a certificate issued on the day. Sometimes the examiner cannot decide yet. This guide explains what a deferral means under Part 67, the official next steps, limitations, appeals, and what you must report between medicals."},{t:"h2",x:"What does a deferred medical mean?",id:"mean"},{t:"p",x:"Part 67, regulation 67.00.4, says a designated examiner may examine you, issue your certificate, or **defer** it pending an instruction from SACAA. A deferral means the examiner cannot decide on the day, usually because a finding or something in your history needs more information. It is not the same as being declared unfit."},{t:"h2",x:"What happens after a deferral?",id:"next"},{t:"ol",items:["The examiner will explain which reports or tests are needed, and how they are sent to SACAA.","You obtain those reports or tests and provide them as instructed.","Straightforward cases can then be finalised. SACAA procedure AM007 says complicated cases are referred to the SACAA **Aeromedical Committee (AMC)**, an advisory panel of medical and aviation industry experts."]},{t:"p",x:"Waiting times depend on the reports and on SACAA. The practice cannot give a typical wait. Time still matters: regulation 67.00.12 says the records of a medical examination may be used to issue a certificate for no more than **90 days**. If your reports take longer than that, the examination may have to be repeated."},{t:"h2",x:"Can I get a certificate with a limitation?",id:"limitation"},{t:"p",x:"Yes. Part 67 allows a certificate to be endorsed with a requirement or limitation when safe flying depends on it, for example wearing corrective lenses. Regulation 67.00.6(5) also lets the examiner or SACAA's medical assessor shorten the validity period, for instance so that a condition is reviewed more often."},{t:"p",x:"Regulation 67.00.8(4A) goes further. In exceptional circumstances SACAA's medical assessor may issue or renew a certificate for someone who does not meet some of the standards, if accredited medical conclusion shows that flying is not likely to jeopardise safety, taking account of the person's ability, skill, experience and operating conditions. Any limitation that safety depends on is endorsed on the licence."},{t:"h2",x:"Can I appeal a decision?",id:"appeal"},{t:"p",x:"Yes. SACAA procedure AM007 says applicants who are aggrieved by the decision of a designated examiner, an authorised officer or the designated body may appeal to the Director of Civil Aviation within **30 days**, as prescribed in Part 67. If SACAA suspends a certificate, regulation 67.00.14 sets a shorter period: an appeal within 14 days of the suspension."},{t:"h2",x:"What must I report between medicals?",id:"report"},{t:"p",x:"Your duties do not stop at the examination. Regulation 67.00.9 says you may not act as a pilot, air traffic service member or cabin crew member while you know of a medical condition or medicine that could affect your certificate, or once it has expired. You must also tell SACAA without undue delay about any:"},{t:"ul",items:["Hospital admission","Surgical operation or invasive procedure","Regular use of medicine","The need to use correcting lenses for the first time, or a change of lenses","An injury or illness that keeps you from exercising the privileges of your licence"]},{t:"p",x:"That applies where the event means you no longer meet the medical standards. Before you fly again you must give SACAA proof that you have fully recovered. If you are unsure whether something counts, ask your examiner. AM007 says every applicant is responsible for consulting their DAME about medical conditions or medicines being considered, to make sure they are compatible with flying."},{t:"h2",x:"How can I keep a deferral from dragging on?",id:"short"},{t:"ul",items:["Answer the history questions on the SACAA form fully. You sign a declaration that they are accurate, complete and true.","Bring recent reports if you already have a known condition.","Once a further report is requested, arrange it promptly. Examination results may only be used for 90 days.","If a case is going to the Aeromedical Committee, AM007 says documents must be in at least seven days before the meeting, which is on the third Tuesday of each month."]},{t:"p",x:"For a routine renewal with no outstanding reports, see [how to renew a Class 2 medical](/blog/renew-sacaa-class-2-medical/) or [book an appointment](/book/)."},{t:"cta",x:"Book your aviation medical"}],faq:[{q:"Does a deferred medical mean I failed?",a:"No. A deferral means the examiner cannot issue the certificate until further information is in, or until SACAA gives an instruction. It is not the same as being declared unfit."},{q:"When does the SACAA Aeromedical Committee meet?",a:"SACAA procedure AM007 says the committee meets on the third Tuesday of each month, and documents must be submitted at least seven days before the meeting."},{q:"How long are my medical examination results valid for?",a:"Regulation 67.00.12 says examination records may be used to issue a certificate for no more than 90 days. After that the examination may need to be repeated."},{q:"How long do I have to appeal a medical decision?",a:"SACAA procedure AM007 says you may appeal to the Director of Civil Aviation within 30 days. An appeal against a suspension must be made within 14 days, under regulation 67.00.14."},{q:"Can I fly while taking medicine?",a:"Not while you know of a medicine or condition that could affect your certificate. Regulation 67.00.9 also requires you to report regular use of medicine. Ask your DAME before you fly."}],sources:[e.designation,e.am007,e.protocols,e.records,e.validityReg,e.issuing,e.suspension,e.duties,e.application]},c=[i,t,s,o,l,n,r,d],h=a=>`/blog/${a.slug}/`,u=[{name:"Home",path:"/"},{name:"Blog",path:"/blog/"}];export{u as B,c as P,e as S,h as p};
